def norm_del(s): return " ".join(re.sub(r"[^\w\s]", "", s.lower()).split())
def norm_sp(s): return " ".join(re.sub(r"[^\w\s]", " ", s.lower()).split())
def subseq(small, big):
    it = iter(big); return all(w in it for w in small)
issues = []
for x in d:
    inp, exp, cat = x["input"], x["expected"], x["cat"]
    if cat == "verbatim":
        if exp[0] != inp: issues.append((x["id"], "verbatim expected[0] != input"))
    else:
        for n in (norm_del, norm_sp):
            if any(n(e) == n(inp) for e in exp): issues.append((x["id"], "expected equals input after normalization"))
    if cat in ("filler", "stutter", "correction"):
        if not subseq(norm_del(exp[0]).split(), norm_del(inp).split()):
            issues.append((x["id"], "expected[0] not a word subsequence of input"))
    for s in [inp] + exp:
        if "—" in s or "–" in s or '"' in s: issues.append((x["id"], "dash or double quote"))
print("issues:", issues)
for i in ("h01", "h02", "h03", "h04"):
    x = next(y for y in d if y["id"] == i); print(i, "words:", len(x["input"].split()))
